using namespace std;
int main(){
    string s,t; cin>>s>>t;
    int n=s.size(), m=t.size();
    vector<int> pre(m+1), suf(m+1);
    pre[0]=-1; int j=0;
    for(int p=0;p<n && j<m;p++) if(s[p]==t[j]){ j++; pre[j]=p; }
    suf[m]=n; int k=m-1;
    for(int p=n-1;p>=0 && k>=0;p--) if(s[p]==t[k]){ suf[k]=p; k--; }
    int ans=0;
    for(int i=0;i<=m;i++) ans=max(ans, suf[i]-pre[i]-1);
    cout<<ans<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin>>n;
    map<long long,int> cnt;
    for(int i=0;i<n*n;i++){ long long x; cin>>x; cnt[x]++; }
    vector<long long> ans;
    for(int it=0; it<n; it++){
        // largest value still present must be an array element
        auto itv = prev(cnt.end());
        while(itv->second==0){ itv = prev(itv); }
        long long v = itv->first;
        for(long long b: ans){ cnt[__gcd(v,b)] -= 2; }
        cnt[v] -= 1;
        ans.push_back(v);
    }
    for(size_t i=0;i<ans.size();i++) cout<<ans[i]<<(i+1<ans.size()?' ':'\n');
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; long long M; cin>>n>>M;
    vector<int> t(n);
    for(auto &x:t) cin>>x;
    int cnt[101]={0};
    long long pre=0;   // sum of times of students 1..i-1 (all passing)
    for(int i=0;i<n;i++){
        long long need = pre + t[i] - M;  // time that must be freed from earlier students
        long long used = 0;
        if(need>0){
            // greedily fail the largest earlier times first (cnt holds earlier students)
            for(int v=100; v>=1 && need>0; v--){
                if(cnt[v]==0) continue;
                long long k = min<long long>(cnt[v], (need+v-1)/v);
                used += k; need -= k*v;
            }
        }
        cout<<used<<(i+1<n?' ':'\n');
        cnt[t[i]]++; pre += t[i];
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; string s; cin>>n>>s;
    auto fail=[&](){ cout<<":(\n"; exit(0); };
    if(n%2) fail();
    if(s[0]==')') fail();
    if(s[n-1]=='(') fail();
    if(s[0]=='?') s[0]='(';
    if(s[n-1]=='?') s[n-1]=')';
    string orig=s;
    int open=0;
    for(int i=1;i<n-1;i++){ if(s[i]=='?') s[i]=')'; if(s[i]=='(') open++; }
    open += 1;               // s[0] is '('
    int k = n/2 - open;      // extra '(' needed among middle '?'
    if(k<0) fail();
    for(int i=1;i<n-1 && k>0;i++) if(orig[i]=='?'){ s[i]='('; k--; }
    if(k>0) fail();
    int bal=0;
    for(int i=0;i<n;i++){
        bal += (s[i]=='(')?1:-1;
        if(bal<0) fail();
        if(bal==0 && i<n-1) fail();
    }
    if(bal!=0) fail();
    cout<<s<<"\n";
}

