int main(){
    int t; cin>>t;
    while(t--){
        int n,k; cin>>n>>k;
        vector<int> a(n);
        for(auto &x:a) cin>>x;
        int best=INT_MAX;
        for(int L=0; L<=a[0]; L++){          // candidate lower bound of all floor values
            int mx=INT_MIN, mn=INT_MAX;
            for(int x: a){
                int v;
                if(L==0) v = x/k;              // p = k gives the smallest value
                else { int p=min(k, x/L); v = x/p; } // largest p keeping floor >= L
                mx=max(mx,v); mn=min(mn,v);
            }
            best=min(best,mx-mn);
        }
        cout<<best<<"\n";
    }
}

