#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; cin>>t;
    while(t--){
        int n; cin>>n;
        vector<long long> a(n);
        for(auto &x:a) cin>>x;
        vector<long long> v=a;
        sort(v.begin(),v.end()); v.erase(unique(v.begin(),v.end()),v.end());
        int m=v.size();
        vector<int> bit(m+1,0);
        auto add=[&](int i){ for(;i<=m;i+=i&-i) bit[i]++; };
        auto qry=[&](int i){ int s=0; for(;i>0;i-=i&-i) s+=bit[i]; return s; };
        long long ans=0;
        for(int i=0;i<n;i++){
            int r=lower_bound(v.begin(),v.end(),a[i])-v.begin()+1;
            long long less=qry(r-1);
            long long greater=i-qry(r);     // existing elements strictly greater
            ans+=min(less,greater);         // push front or back, whichever adds fewer inversions
            add(r);
        }
        cout<<ans<<"\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// smallest y >= x with (y & mask) == mask
ll minSuper(ll x, ll mask){
    ll miss = mask & ~x;
    if(!miss) return x;
    int h = 63 - __builtin_clzll(miss);
    ll low = mask & ((1LL<<h)-1);
    return ((x>>(h+1))<<(h+1)) | (1LL<<h) | low;
}
int main(){
    int n,q; cin>>n>>q;
    vector<ll> a(n);
    for(auto &x:a) cin>>x;
    while(q--){
        ll k; cin>>k;
        ll ans=0;
        for(int b=61;b>=0;b--){
            ll cand = ans | (1LL<<b);
            ll cost=0; bool ok=true;
            for(ll x: a){
                cost += minSuper(x,cand)-x;
                if(cost>k){ ok=false; break; }
            }
            if(ok) ans=cand;
        }
        cout<<ans<<"\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m,d; cin>>n>>m>>d;
    vector<int> c(m);
    long long sum=0;
    for(auto &x:c){ cin>>x; sum+=x; }
    long long e = n - sum;                 // empty cells to distribute
    if(e > (long long)(m+1)*(d-1)){ cout<<"NO\n"; return 0; }
    vector<int> out(n,0);
    long long rem=e; int pos=1;            // 1-indexed next cell
    for(int j=0;j<=m;j++){
        long long g=min<long long>(d-1, rem);   // empties in gap j
        rem-=g; pos+=g;
        if(j<m){
            for(int t=0;t<c[j];t++) out[pos-1+t]=j+1;
            pos+=c[j];
        }
    }
    cout<<"YES\n";
    for(int i=0;i<n;i++) cout<<out[i]<<(i+1<n?' ':'\n');
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    const int MX=100001;
    vector<int> spf(MX,0);
    for(int i=2;i<MX;i++) if(!spf[i]) for(int j=i;j<MX;j+=i) if(!spf[j]) spf[j]=i;
    int t; cin>>t;
    while(t--){
        int n,m; cin>>n>>m;
        vector<int> S(m);
        for(auto &x:S) cin>>x;
        sort(S.rbegin(), S.rend());            // descending
        vector<int> om(n+1,0);                 // number of prime factors with multiplicity
        int L=0;
        for(int i=2;i<=n;i++){ om[i]=om[i/spf[i]]+1; L=max(L,om[i]); }
        if(m < L+1){ cout<<-1<<"\n"; continue; }
        for(int i=1;i<=n;i++) cout<<S[om[i]]<<(i<n?' ':'\n');
    }
}

