int n,m,w; vector<long long> a;
bool ok(long long H){
    vector<long long> diff(n+1,0);   // diff[i] = watering ending before i
    long long added=0, days=0;
    for(int i=0;i<n;i++){
        added -= diff[i];
        long long need = H - (a[i] + added);
        if(need>0){
            days += need;
            if(days>m) return false;
            added += need;
            diff[min(n, i+w)] += need;   // window starting at i covers [i, i+w-1]
        }
    }
    return true;
}
