    vector<long long> a(n);
    for(auto &x:a) cin>>x;
    sort(a.rbegin(), a.rend());           // strongest first
    auto ok=[&](int d){                    // d days; cup j is drunk at position j/d in its day
        long long tot=0;
        for(int j=0;j<n;j++){
            long long v=a[j]-(j/d);
            if(v>0) tot+=v;
            if(tot>=m) return true;
