}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin>>n;
    vector<string> typ(2*n);
    vector<int> val(2*n,0);
    for(int i=0;i<2*n;i++){
        cin>>typ[i];
        if(typ[i]=="-") cin>>val[i];
    }
    // reverse pass: a sale pushes its price, a placement takes the most recent pending sale
    vector<int> st;
    vector<int> placed; // prices by placement index in reverse order
    vector<int> assign(2*n,0);
    for(int i=2*n-1;i>=0;i--){
        if(typ[i]=="-") st.push_back(val[i]);
        else {
            if(st.empty()){ cout<<"NO\n"; return 0; }
            assign[i]=st.back(); st.pop_back();
        }
    }
    // forward check: each sale must sell the current minimum
    multiset<int> disp; vector<int> order;
    for(int i=0;i<2*n;i++){
        if(typ[i]=="+"){ disp.insert(assign[i]); order.push_back(assign[i]); }
        else {
            if(disp.empty() || *disp.begin()!=val[i]){ cout<<"NO\n"; return 0; }
            disp.erase(disp.begin());
        }
    }
    cout<<"YES\n";
    for(size_t i=0;i<order.size();i++) cout<<order[i]<<(i+1<order.size()?' ':'\n');
}
